// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, Easing } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadDMSans = makeLoadFont('DMSans');
const loadPoppins = makeLoadFont('Poppins');

// Load font families at the module level to ensure they are ready before frame 0
const { fontFamily: interFamily } = loadInter();
const { fontFamily: dmSansFamily } = loadDMSans();
const { fontFamily: poppinsFamily } = loadPoppins();

// Map font options to their loaded family strings
const fontMap = {
  "Inter": interFamily,
  "DM Sans": dmSansFamily,
  "Poppins": poppinsFamily,
};



export type LiquidGlassStatProps = Record<string, any>;

const SubStat: React.FC<{ value: string; label: string; fade: number; s: number; textColor: string }> = ({ value, label, fade, s, textColor }) => {
  return (
    <div style={{
      display: "flex",
      flexDirection: "column",
      opacity: fade,
      transform: `translateY(${(1 - fade) * 20 * s}px)`,
      transition: "none",
    }}>
      <div style={{
        fontSize: 48 * s,
        fontWeight: 700,
        color: textColor,
        textShadow: `0 ${2 * s}px ${6 * s}px rgba(0,0,0,0.15)`,
        letterSpacing: "-1px"
      }}>
        {value}
      </div>
      <div style={{
        fontSize: 28 * s,
        fontWeight: 400,
        color: textColor,
        opacity: 0.7,
        marginTop: 6 * s
      }}>
        {label}
      </div>
    </div>
  );
};

const LiquidGlassStat: React.FC<LiquidGlassStatProps> = ({
  backgroundColor = "#111111",
  transparentBackground = true,
  durationInSeconds = 8, // unused directly in logic, defines total duration via composition
  heroValue = 5.03,
  heroLabel = "Kilometres",
  subStat1Value = "7'05\"",
  subStat1Label = "Pace",
  subStat2Value = "35:35",
  subStat2Label = "Time",
  subStat3Value = "342",
  subStat3Label = "Calories",
  hookText = "A quick run to start the day",
  hookTextFontSize = 40,
  hookTextFontFamily = "Inter",
  textColor = "#ffffff",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  // Parser safety for transparency
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Timing & Interpolation ---

  // Card drifts down and settles
  const cardEnter = spring({ frame: frame - 5, fps, config: { damping: 14, mass: 0.9 } });
  const cardEnterY = interpolate(cardEnter, [0, 1], [-80 * s, 0]);
  const cardOpacity = interpolate(cardEnter, [0, 1], [0, 1]);

  // Initial fast sweeps over the glass
  const sweepProgress = interpolate(frame, [10, 40], [-1, 2], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const sweepX = sweepProgress * 300 - 100;

  // Count up the hero value
  const countProgress = interpolate(frame, [25, 60], [0, 1], { 
    extrapolateRight: "clamp", 
    extrapolateLeft: "clamp", 
    easing: Easing.bezier(0.2, 0.8, 0.2, 1) 
  });
  const currentHeroValue = countProgress * heroValue;

  // Staggered fade for sub-stats
  const fade1 = spring({ frame: frame - 40, fps, config: { damping: 16 } });
  const fade2 = spring({ frame: frame - 45, fps, config: { damping: 16 } });
  const fade3 = spring({ frame: frame - 50, fps, config: { damping: 16 } });

  // Ambient light drift on the card surface
  const driftX = Math.sin(frame / 70) * 30 + 50;
  const driftY = Math.cos(frame / 80) * 30 + 50;

  const hookWords = hookText.split(" ");
  const activeHookFontFamily = fontMap[hookTextFontFamily] || interFamily;

  // --- Styles ---

  const cardStyle: React.CSSProperties = {
    width: "100%",
    boxSizing: "border-box",
    borderRadius: 40 * s,
    padding: 48 * s,
    background: "linear-gradient(135deg, rgba(255,255,255,0.25) 0%, rgba(255,255,255,0.05) 100%)",
    backdropFilter: "blur(24px) saturate(120%)",
    WebkitBackdropFilter: "blur(24px) saturate(120%)",
    borderTop: `${2 * s}px solid rgba(255,255,255,0.6)`,
    borderLeft: `${2 * s}px solid rgba(255,255,255,0.6)`,
    borderRight: `${1 * s}px solid rgba(255,255,255,0.2)`,
    borderBottom: `${1 * s}px solid rgba(255,255,255,0.2)`,
    boxShadow: `0 ${20 * s}px ${40 * s}px rgba(0,0,0,0.15), inset 0 0 ${20 * s}px rgba(255,255,255,0.15)`,
    position: "relative",
    overflow: "hidden",
  };

  const highlightStyle: React.CSSProperties = {
    position: "absolute",
    top: 0,
    left: 0,
    right: 0,
    height: "45%",
    background: "linear-gradient(180deg, rgba(255,255,255,0.4) 0%, rgba(255,255,255,0) 100%)",
    pointerEvents: "none",
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily }}>
      
      {/* Positioned in the top third; safe zone margin from top; floating transform removed */}
      <div style={{
        position: "absolute",
        top: height * 0.07,
        left: 0,
        width: "100%",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        transition: "none",
      }}>
        
        {/* The Liquid Glass Card */}
        <div style={{
          width: "85%",
          transform: `translateY(${cardEnterY}px)`,
          opacity: cardOpacity,
          display: "flex",
          flexDirection: "column",
          transition: "none",
        }}>
          
          <div style={cardStyle}>
            {/* Ambient slow drift */}
            <div style={{
              position: "absolute",
              top: 0, left: 0, right: 0, bottom: 0,
              background: `radial-gradient(circle at ${driftX}% ${driftY}%, rgba(255,255,255,0.2) 0%, transparent 60%)`,
              pointerEvents: "none",
              transition: "none",
            }} />

            {/* Specular Top Highlight */}
            <div style={highlightStyle} />

            {/* Fast Sweeps (White and Chromatic) */}
            <div style={{
              position: "absolute",
              top: 0, left: 0, bottom: 0,
              width: "60%",
              background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.5), transparent)",
              transform: `skewX(-25deg) translateX(${sweepX}%)`,
              pointerEvents: "none",
              transition: "none",
            }} />
            <div style={{
              position: "absolute",
              top: 0, left: 0, bottom: 0,
              width: "40%",
              background: "linear-gradient(90deg, transparent, rgba(255,0,150,0.15), rgba(0,255,255,0.15), transparent)",
              transform: `skewX(-25deg) translateX(${sweepX * 1.2}%)`,
              pointerEvents: "none",
              transition: "none",
            }} />

            {/* Card Content (z-index ensures text stays above highlights) */}
            <div style={{ position: "relative", zIndex: 1, display: "flex", flexDirection: "column", width: "100%" }}>
              
              {/* Hero Number */}
              <div style={{
                fontSize: 150 * s,
                fontWeight: 900,
                fontStyle: "italic",
                lineHeight: 1,
                color: textColor,
                textShadow: `0 ${4 * s}px ${12 * s}px rgba(0,0,0,0.2)`,
                letterSpacing: "-2px"
              }}>
                {currentHeroValue.toFixed(2)}
              </div>
              <div style={{
                fontSize: 36 * s,
                color: textColor,
                opacity: 0.7,
                marginTop: 10 * s,
                fontWeight: 400
              }}>
                {heroLabel}
              </div>

              {/* Spacer */}
              <div style={{ height: 64 * s }} />

              {/* Sub-stats Row */}
              <div style={{
                display: "flex",
                flexDirection: "row",
                justifyContent: "space-between",
                width: "100%"
              }}>
                <SubStat value={subStat1Value} label={subStat1Label} fade={fade1} s={s} textColor={textColor} />
                <SubStat value={subStat2Value} label={subStat2Label} fade={fade2} s={s} textColor={textColor} />
                <SubStat value={subStat3Value} label={subStat3Label} fade={fade3} s={s} textColor={textColor} />
              </div>

            </div>
          </div>
        </div>

        {/* The Hook Line beneath the card */}
        <div style={{
          marginTop: 40 * s,
          display: "flex",
          flexDirection: "row",
          flexWrap: "wrap",
          justifyContent: "center",
          gap: 14 * s,
          width: "85%",
        }}>
          {hookWords.map((word, i) => {
            const wordEnter = spring({ frame: frame - 55 - (i * 4), fps, config: { damping: 12 } });
            const wordOpacity = interpolate(wordEnter, [0, 1], [0, 1]);
            const wordY = interpolate(wordEnter, [0, 1], [30 * s, 0]);
            const blurAmt = interpolate(wordEnter, [0, 1], [15, 0]);
            const scaleAmt = interpolate(wordEnter, [0, 1], [0.8, 1]);

            return (
              <div key={i} style={{
                fontFamily: activeHookFontFamily,
                fontSize: hookTextFontSize * s,
                fontWeight: 600,
                color: textColor,
                opacity: wordOpacity,
                transform: `translateY(${wordY}px) scale(${scaleAmt})`,
                filter: `blur(${blurAmt}px) brightness(${1 + blurAmt * 0.1})`,
                textShadow: `0 ${4 * s}px ${12 * s}px rgba(0,0,0,0.3)`,
                lineHeight: 1.2,
                transition: "none",
              }}>
                {word}
              </div>
            );
          })}
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default LiquidGlassStat;